from itertools import permutations

# Explicit finite inputs; replace PAIRS by any finite list of positive pairs.
PAIRS = [(i, j) for i in range(1, 7) for j in range(1, 7)]
WITNESS = (3, 2)

def size(p):
    return sum(p)

def contains(mu, lam):
    return all((mu[t] if t < len(mu) else 0) >= a for t, a in enumerate(lam))

def in_box(p, q, r):
    return len(p) <= r and (not p or p[0] <= q)

def partitions_in_box(q, r, total, cap=None):
    if cap is None:
        cap = q
    if total == 0:
        yield ()
        return
    if r == 0:
        return
    for a in range(min(cap, total), 0, -1):
        for tail in partitions_in_box(q, r - 1, total - a, a):
            yield (a,) + tail

def interval_columns(i, j, k):
    q, r, d = i + 1, j + 1, i * j
    base = (i,) * j
    return sorted(p for p in partitions_in_box(q, r, d + k)
                  if contains(p, base))

def expected_column(i, j, k, x):
    y = k - x
    return (i + 1,) * x + (i,) * (j - x) + (() if y == 0 else (y,))

def one_box_extensions(lam, i, j):
    q, r = i + 1, j + 1
    # Independent exhaustive definition: all box partitions of size |lam|+1 containing lam.
    return sorted(p for p in partitions_in_box(q, r, size(lam) + 1)
                  if contains(p, lam))

def det(A):
    n = len(A)
    if n == 0:
        return 1
    assert all(len(row) == n for row in A)
    ans = 0
    for perm in permutations(range(n)):
        inv = sum(perm[a] > perm[b] for a in range(n) for b in range(a + 1, n))
        term = 1
        for row in range(n):
            term *= A[row][perm[row]]
        ans += -term if inv % 2 else term
    return ans

def checker(i, j, emit=False):
    assert isinstance(i, int) and isinstance(j, int) and i >= 1 and j >= 1
    b = min(i, j)
    checked_columns = checked_extensions = 0
    witness_lines = []
    for k in range(b + 1):
        cols = interval_columns(i, j, k)
        expected_cols = [expected_column(i, j, k, x) for x in range(k + 1)]
        assert cols == sorted(expected_cols), (i, j, k, cols, expected_cols)
        checked_columns += 1
        if k == 0:
            assert det([]) == 1
            if emit:
                witness_lines.append('k=0 columns=[%s] rows=[] det_retain_C0=1 det_retain_Ck=1' % (cols[0],))
            continue
        prev = interval_columns(i, j, k - 1)
        expected_prev = [expected_column(i, j, k - 1, x) for x in range(k)]
        assert prev == sorted(expected_prev)
        # Index by the mathematical order C_x=P_{x,k-x}, not lexicographic order.
        ordered_cols = expected_cols
        rows = []
        ext_lists = []
        for x, lam in enumerate(expected_prev):
            got = one_box_extensions(lam, i, j)
            want = sorted([expected_column(i, j, k, x), expected_column(i, j, k, x + 1)])
            assert got == want, (i, j, k, x, lam, got, want)
            checked_extensions += 1
            rows.append([int(c in got) for c in ordered_cols])
            ext_lists.append((lam, got))
        # Retain C_0: delete column 0. Retain C_k: delete column k.
        left = [row[1:] for row in rows]
        right = [row[:-1] for row in rows]
        dl, dr = det(left), det(right)
        assert dl == dr == 1, (i, j, k, left, right, dl, dr)
        if emit:
            witness_lines.append('k=%d columns=%s extensions=%s det_retain_C0=%d det_retain_Ck=%d' %
                                 (k, ordered_cols, ext_lists, dl, dr))
    return checked_columns, checked_extensions, witness_lines

column_tests = extension_tests = 0
for i, j in PAIRS:
    c, e, lines = checker(i, j, emit=((i, j) == WITNESS))
    column_tests += c
    extension_tests += e
print('INPUT_PAIRS:', PAIRS)
print('PAIR_COUNT:', len(PAIRS))
print('K_VALUES_CHECKED:', column_tests)
print('ONE_BOX_EXTENSION_LISTS_CHECKED:', extension_tests)
print('WITNESS_PAIR:', WITNESS)
for line in checker(*WITNESS, emit=True)[2]:
    print(line)
print('RESULT: PASS')
